# <<< SPEC

# >>> HINTS
# %%pgrep
# Use the man page text (man pgrep) as the help source; `pgrep --help` prints only a compact usage summary.
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_cgroup() {
    gawk -F: '$1 == "0" && $3 != "" { print $3 }' /proc/[0-9]*/cgroup 2>/dev/null
}

_choice_group() {
    compgen -g
}

_choice_ns() {
    _choice_pid
}

_choice_parent() {
    _choice_pid
}

_choice_pattern() {
    ps -eo comm= | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e '/^$/d'
}

_choice_pgroup() {
    ps -eo pgid=,comm= | gawk 'NF >= 2 {
        pgid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print pgid "\t" $0
    }'
}

_choice_pid() {
    ps -eo pid=,comm= | gawk 'NF >= 2 {
        pid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print pid "\t" $0
    }'
}

_choice_runstates() {
    printf '%s\t%s\n' \
        D 'uninterruptible sleep' I 'idle kernel thread' R 'running' S 'sleeping' \
        T 'stopped' t 'tracing stop' W 'paging' X 'dead' Z 'zombie' \
        | _argc_util_comp_multi ,
}

_choice_session() {
    ps -eo sess=,comm= | gawk 'NF >= 2 {
        sid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print sid "\t" $0
    }'
}

_choice_signal() {
    command kill -l 2>/dev/null | gawk '{
        for (i = 1; i <= NF; i++) {
            if ($i ~ /^SIG[A-Z][A-Z0-9]*$/) print $i
            else if ($i ~ /^[A-Z][A-Z0-9]*$/) print "SIG" $i
        }
    }'
}

_choice_terminal() {
    ps -eo tty= | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e '/^$/d' -e '/^?$/d'
}

_choice_user() {
    compgen -u
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
